exercises.starter:
def grounded(text, value):
    """True if the number `value` appears in `text` as a whole number (thousands commas allowed)."""
    return str(value) in text

exercises.reference:
import re

def grounded(text, value):
    numbers = {float(n.replace(",", "")) for n in re.findall(r"\d[\d,]*(?:\.\d+)?", text)}
    return float(value) in numbers
